        { text: row[2], options: { fill: { color: "E8F5E9" }, color: COLORS.positive, bold: true, align: "center" } }
      ];
    } else if (i === 2) {
      return [
        { text: row[0], options: { fill: { color: "FFEBEE" }, color: COLORS.negative, bold: true } },
        { text: row[1], options: { fill: { color: "FFEBEE" }, color: COLORS.negative, bold: true, align: "center" } },
        { text: row[2], options: { fill: { color: "FFEBEE" }, color: COLORS.negative, bold: true, align: "center" } }
