    } else {
      return [
        { text: row[0], options: { fill: { color: COLORS.white }, color: COLORS.text } },
        { text: row[1], options: { fill: { color: COLORS.white }, color: COLORS.text, align: "center" } },
        { text: row[2], options: { fill: { color: COLORS.white }, color: COLORS.warning, align: "center" } }
      ];
    }
  });

  slide.addTable(tableRows, {
    x: 0.5, y: 1.4, w: 9, h: 3.2,
    colW: [5, 2, 2],
    fontFace: "Calibri",
    fontSize: 12,
    border: { pt: 0.5, color: COLORS.gridLine },
    valign: "middle"
  });

  // Key insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.75, w: 9, h: 0.7,
    fill: { color: "FFEBEE" }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.75, w: 0.08, h: 0.7, fill: { color: COLORS.negative }
  });
  slide.addText("Critical Finding: Value-Pretraining is the single most impactful component. Without it, value-model-based RL barely works (drops from 60 to 11).", {
    x: 0.75, y: 4.85, w: 8.6, h: 0.5,
    fontSize: 13, fontFace: "Calibri", color: COLORS.text, bold: true
  });

  // ============================================
  // SLIDE 9: Key Takeaways
  // ============================================
  slide = pres.addSlide();
  slide.background = { color: COLORS.darkBg };

  // Accent bar at top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08, fill: { color: COLORS.accent }
  });

  // Title
  slide.addText("Key Takeaways", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 36, fontFace: "Arial Black", color: COLORS.white, margin: 0
  });

  const takeaways = [
    { num: "1", text: "Value-model-based RL can surpass value-model-free methods when core challenges (bias, heterogeneous lengths, reward sparsity) are systematically addressed." },
    { num: "2", text: "Length-adaptive GAE is a novel technique that dynamically optimizes the bias-variance tradeoff across heterogeneous response lengths." },
    { num: "3", text: "Value-Pretraining is the single most important component — without it, value-model-based RL barely works (49-point drop from 60 to 11)." },
    { num: "4", text: "VAPO is highly training-efficient and stable, reaching SOTA in ~5,000 steps with zero training crashes across multiple runs." },
    { num: "5", text: "Implications: The path to better reasoning models lies in sophisticated credit assignment, not just more data or larger models." }
  ];

  const takeY = 1.15;
  const takeH = 0.85;
  const takeGap = 0.08;

  takeaways.forEach((t, i) => {
    const y = takeY + i * (takeH + takeGap);

    // Number circle
    slide.addShape(pres.shapes.OVAL, {
      x: 0.5, y: y + 0.15, w: 0.45, h: 0.45,
      fill: { color: COLORS.accent }
    });
    slide.addText(t.num, {
      x: 0.5, y: y + 0.18, w: 0.45, h: 0.4,
      fontSize: 16, fontFace: "Arial Black", color: COLORS.white, align: "center", valign: "middle", margin: 0
    });

    // Text
    slide.addText(t.text, {
      x: 1.1, y: y + 0.1, w: 8.4, h: takeH - 0.1,
      fontSize: 13, fontFace: "Calibri", color: COLORS.white, valign: "middle"
    });
  });

  // Footer
  slide.addText("VAPO: Value-Model-Based RL for Advanced Reasoning  |  ByteDance Seed  |  arXiv:2504.05118", {
    x: 0.5, y: 5.25, w: 9, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: COLORS.textMuted
  });

  // Save presentation
  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Presentation saved to /app/output/final_deck.pptx");
}

createPresentation().catch(console.error);

