const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const {
  FaBrain, FaChartLine, FaCogs, FaLightbulb, FaRocket, FaCheckCircle, FaExclamationTriangle, FaBalanceScale, FaCodeBranch
} = require("react-icons/fa");
const {
  HiLightBulb, HiChip
} = require("react-icons/hi");
const {
  BiNetworkChart
} = require("react-icons/bi");
const {
  MdTimeline, MdSettings, MdAutoGraph
} = require("react-icons/md");
const {
  TbHierarchy3, TbMath
} = require("react-icons/tb");

// Icon helper functions
function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// Color palette - Midnight Executive with teal accent for tech/ML feel
const COLORS = {
  darkBg: "0F172A",      // Dark slate
  darkBg2: "1E293B",      // Slightly lighter slate
  primary: "0EA5E9",     // Sky blue
  accent: "06B6D4",       // Cyan
  accent2: "22D3EE",      // Light cyan
  white: "FFFFFF",
  lightBg: "F8FAFC",      // Very light slate
  text: "1E293B",         // Dark text
  textMuted: "64748B",    // Muted text
  gridLine: "E2E8F0",
  positive: "10B981",     // Green
  negative: "EF4444",     // Red
  warning: "F59E0B",      // Amber
};

// Shadow factory
const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.2 });

async function createPresentation() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.title = "VAPO: Value-Model-Based RL for Advanced Reasoning";
  pres.author = "ByteDance Seed";

  // Pre-generate icons
  const iconBrain = await iconToBase64Png(FaBrain, "#" + COLORS.accent, 256);
  const iconChart = await iconToBase64Png(FaChartLine, "#" + COLORS.accent, 256);
  const iconCogs = await iconToBase64Png(FaCogs, "#" + COLORS.accent, 256);
  const iconLightbulb = await iconToBase64Png(FaLightbulb, "#" + COLORS.accent, 256);
  const iconRocket = await iconToBase64Png(FaRocket, "#" + COLORS.accent, 256);
  const iconCheck = await iconToBase64Png(FaCheckCircle, "#" + COLORS.positive, 256);
  const iconWarning = await iconToBase64Png(FaExclamationTriangle, "#" + COLORS.warning, 256);
  const iconBalance = await iconToBase64Png(FaBalanceScale, "#" + COLORS.accent, 256);
  const iconCode = await iconToBase64Png(FaCodeBranch, "#" + COLORS.accent, 256);
  const iconMath = await iconToBase64Png(TbMath, "#" + COLORS.white, 256);

  // ============================================
  // SLIDE 1: Title Slide
  // ============================================
  let slide = pres.addSlide();
  slide.background = { color: COLORS.darkBg };

  // Accent bar at top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08, fill: { color: COLORS.accent }
  });

  // Title
  slide.addText("VAPO", {
    x: 0.6, y: 1.2, w: 8.8, h: 1.0,
    fontSize: 72, fontFace: "Arial Black", color: COLORS.white, bold: true
  });

  // Subtitle
  slide.addText("Value-Model-Based RL for Advanced Reasoning", {
    x: 0.6, y: 2.1, w: 8.8, h: 0.6,
    fontSize: 28, fontFace: "Calibri", color: COLORS.accent
  });

  // Key result callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 3.0, w: 4.5, h: 1.4,
    fill: { color: COLORS.darkBg2 },
    shadow: makeShadow()
  });
  slide.addText("60.4", {
    x: 0.7, y: 3.1, w: 2.2, h: 0.9,
    fontSize: 56, fontFace: "Arial Black", color: COLORS.accent, margin: 0
  });
  slide.addText("AIME 2024", {
    x: 2.8, y: 3.25, w: 2.2, h: 0.5,
    fontSize: 20, fontFace: "Calibri", color: COLORS.white, bold: true
  });
  slide.addText("avg@32  •  Surpasses DAPO by 10+ pts", {
    x: 2.8, y: 3.7, w: 2.2, h: 0.4,
    fontSize: 12, fontFace: "Calibri", color: COLORS.textMuted
  });

  // Model info
  slide.addText("Base Model: Qwen2.5-32B  •  No SFT Data Required", {
    x: 0.6, y: 4.6, w: 8.8, h: 0.4,
    fontSize: 14, fontFace: "Calibri", color: COLORS.textMuted
  });

  // Institution
  slide.addText("ByteDance Seed", {
    x: 0.6, y: 5.1, w: 8.8, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: COLORS.textMuted
  });

  // ============================================
  // SLIDE 2: Motivation - Why Value Models?
  // ============================================
  slide = pres.addSlide();
  slide.background = { color: COLORS.lightBg };

  // Title
  slide.addText("Why Value Models?", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 36, fontFace: "Arial Black", color: COLORS.text, margin: 0
  });
  slide.addText("Finer Credit Assignment for Long Chain-of-Thought Reasoning", {
    x: 0.5, y: 0.9, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Calibri", color: COLORS.textMuted
  });

  // Left card - Value-Free limitations
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.5, w: 4.3, h: 3.6,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  // Red accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.5, w: 0.08, h: 3.6, fill: { color: COLORS.negative }
  });
  slide.addText("Value-Model-Free (GRPO/DAPO)", {
    x: 0.75, y: 1.65, w: 3.9, h: 0.4,
    fontSize: 14, fontFace: "Calibri", color: COLORS.negative, bold: true, margin: 0
  });
  slide.addText([
    { text: "Trajectory-level advantage", options: { bullet: true, breakLine: true } },
    { text: "Uniform credit assignment across all tokens", options: { bullet: true, breakLine: true } },
    { text: "Subtle step errors cause catastrophic failures", options: { bullet: true, breakLine: true } },
    { text: "Limited precision for multi-step reasoning", options: { bullet: true } }
  ], {
    x: 0.75, y: 2.2, w: 3.9, h: 2.6,
    fontSize: 13, fontFace: "Calibri", color: COLORS.text, valign: "top"
  });

  // Right card - Value-Based benefits
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.2, y: 1.5, w: 4.3, h: 3.6,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  // Green accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.2, y: 1.5, w: 0.08, h: 3.6, fill: { color: COLORS.positive }
  });
  slide.addText("Value-Model-Based (VAPO)", {
    x: 5.45, y: 1.65, w: 3.9, h: 0.4,
    fontSize: 14, fontFace: "Calibri", color: COLORS.positive, bold: true, margin: 0
  });
  slide.addText([
    { text: "Token-level credit assignment", options: { bullet: true, breakLine: true } },
    { text: "Traces each action's impact on returns", options: { bullet: true, breakLine: true } },
    { text: "Lower variance estimates per token", options: { bullet: true, breakLine: true } },
    { text: "Generalizes across samples", options: { bullet: true } }
  ], {
    x: 5.45, y: 2.2, w: 3.9, h: 2.6,
    fontSize: 13, fontFace: "Calibri", color: COLORS.text, valign: "top"
  });

  // Bottom insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.2, w: 9, h: 0.35,
    fill: { color: COLORS.accent, transparency: 15 }
  });
  slide.addText("Value models enable precise token-level credit assignment — critical for complex reasoning", {
    x: 0.6, y: 5.22, w: 8.8, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: COLORS.text, italic: true
  });

  // ============================================
  // SLIDE 3: Three Core Challenges
  // ============================================
  slide = pres.addSlide();
  slide.background = { color: COLORS.lightBg };

  // Title
  slide.addText("Three Challenges in Value-Model-Based RL", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 34, fontFace: "Arial Black", color: COLORS.text, margin: 0
  });
  slide.addText("Long chain-of-thought tasks expose fundamental limitations", {
    x: 0.5, y: 0.9, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Calibri", color: COLORS.textMuted
  });

  const challengeY = 1.5;
  const cardH = 3.8;
  const cardW = 2.9;
  const gap = 0.2;

  // Challenge 1
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: challengeY, w: cardW, h: cardH,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: challengeY, w: cardW, h: 0.08, fill: { color: COLORS.warning }
  });
  slide.addText("1", {
    x: 0.7, y: challengeY + 0.2, w: 0.5, h: 0.5,
    fontSize: 28, fontFace: "Arial Black", color: COLORS.warning, margin: 0
  });
  slide.addText("Value Model Bias", {
    x: 0.7, y: challengeY + 0.7, w: 2.5, h: 0.4,
    fontSize: 14, fontFace: "Calibri", color: COLORS.text, bold: true, margin: 0
  });
  slide.addText("Long trajectories compound estimation errors through bootstrapping. The value model becomes increasingly biased as horizon extends.", {
    x: 0.7, y: challengeY + 1.2, w: 2.5, h: 2.4,
    fontSize: 12, fontFace: "Calibri", color: COLORS.text, valign: "top"
  });

  // Challenge 2
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5 + cardW + gap, y: challengeY, w: cardW, h: cardH,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5 + cardW + gap, y: challengeY, w: cardW, h: 0.08, fill: { color: COLORS.primary }
  });
  slide.addText("2", {
    x: 0.5 + cardW + gap + 0.2, y: challengeY + 0.2, w: 0.5, h: 0.5,
    fontSize: 28, fontFace: "Arial Black", color: COLORS.primary, margin: 0
  });
  slide.addText("Heterogeneous Lengths", {
    x: 0.5 + cardW + gap + 0.2, y: challengeY + 0.7, w: 2.5, h: 0.4,
    fontSize: 14, fontFace: "Calibri", color: COLORS.text, bold: true, margin: 0
  });
  slide.addText("Different response lengths require different bias-variance tradeoffs. Short responses need lower variance; long responses need lower bias.", {
    x: 0.5 + cardW + gap + 0.2, y: challengeY + 1.2, w: 2.5, h: 2.4,
    fontSize: 12, fontFace: "Calibri", color: COLORS.text, valign: "top"
  });

  // Challenge 3
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5 + 2*(cardW + gap), y: challengeY, w: cardW, h: cardH,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5 + 2*(cardW + gap), y: challengeY, w: cardW, h: 0.08, fill: { color: COLORS.negative }
  });
  slide.addText("3", {
    x: 0.5 + 2*(cardW + gap) + 0.2, y: challengeY + 0.2, w: 0.5, h: 0.5,
    fontSize: 28, fontFace: "Arial Black", color: COLORS.negative, margin: 0
  });
  slide.addText("Reward Sparsity", {
    x: 0.5 + 2*(cardW + gap) + 0.2, y: challengeY + 0.7, w: 2.5, h: 0.4,
    fontSize: 14, fontFace: "Calibri", color: COLORS.text, bold: true, margin: 0
  });
  slide.addText("Only the final <eos> token receives reward signal. Long reasoning chains suffer from extremely sparse feedback.", {
    x: 0.5 + 2*(cardW + gap) + 0.2, y: challengeY + 1.2, w: 2.5, h: 2.4,
    fontSize: 12, fontFace: "Calibri", color: COLORS.text, valign: "top"
  });

  // ============================================
  // SLIDE 4: VAPO Framework Overview
  // ============================================
  slide = pres.addSlide();
  slide.background = { color: COLORS.darkBg };

  // Title
  slide.addText("VAPO Framework", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 34, fontFace: "Arial Black", color: COLORS.white, margin: 0
  });
  slide.addText("Integrated Solutions for Value-Model-Based Reasoning RL", {
    x: 0.5, y: 0.8, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Calibri", color: COLORS.textMuted
  });

  // Component cards in 2 rows
  const components = [
    { name: "Value-Pretraining", desc: "Pre-trains value model before RL to reduce initial bias", challenge: "Challenge 1", color: COLORS.warning },
    { name: "Decoupled GAE", desc: "Separates GAE computation for robust value estimation (from VC-PPO)", challenge: "Challenge 1", color: COLORS.warning },
    { name: "Length-Adaptive GAE", desc: "Dynamic λ adjustment: short→low λ (low variance), long→high λ (low bias)", challenge: "Challenge 2", color: COLORS.primary },
    { name: "Clip-Higher", desc: "Asymmetric clipping for exploration (from DAPO)", challenge: "Implicit", color: COLORS.textMuted },
    { name: "Token-level Loss", desc: "Normalizes loss at token level vs sequence level (from DAPO)", challenge: "Challenge 3", color: COLORS.negative },
    { name: "Positive Example LM Loss", desc: "Self-imitation learning on correct trajectories", challenge: "Challenge 3", color: COLORS.negative },
    { name: "Group-Sampling", desc: "Multiple responses per prompt for better baseline (from GRPO)", challenge: "Implicit", color: COLORS.textMuted },
  ];

  const compCardW = 2.1;
  const compCardH = 1.5;
  const startX = 0.5;
  const row1Y = 1.3;
  const row2Y = 3.0;
  const compGap = 0.15;

  components.forEach((comp, i) => {
    const row = i < 4 ? 0 : 1;
    const col = i < 4 ? i : i - 4;
    const x = startX + col * (compCardW + compGap);
    const y = row === 0 ? row1Y : row2Y;

    slide.addShape(pres.shapes.RECTANGLE, {
      x: x, y: y, w: compCardW, h: compCardH,
      fill: { color: COLORS.darkBg2 }
    });
    // Color accent on left
    slide.addShape(pres.shapes.RECTANGLE, {
      x: x, y: y, w: 0.06, h: compCardH, fill: { color: comp.color }
    });
    slide.addText(comp.name, {
      x: x + 0.15, y: y + 0.1, w: compCardW - 0.2, h: 0.4,
      fontSize: 11, fontFace: "Calibri", color: COLORS.white, bold: true, margin: 0
    });
    slide.addText(comp.desc, {
      x: x + 0.15, y: y + 0.5, w: compCardW - 0.2, h: 0.9,
      fontSize: 9, fontFace: "Calibri", color: COLORS.textMuted, valign: "top"
    });
  });

  // Challenge legend at bottom
  const legendY = 4.7;
  slide.addText("Challenge Mapping:", {
    x: 0.5, y: legendY, w: 1.5, h: 0.3,
    fontSize: 10, fontFace: "Calibri", color: COLORS.textMuted
  });
  slide.addShape(pres.shapes.RECTANGLE, { x: 2.0, y: legendY + 0.08, w: 0.3, h: 0.15, fill: { color: COLORS.warning } });
  slide.addText("Bias", { x: 2.35, y: legendY, w: 0.6, h: 0.3, fontSize: 9, fontFace: "Calibri", color: COLORS.textMuted });
  slide.addShape(pres.shapes.RECTANGLE, { x: 3.0, y: legendY + 0.08, w: 0.3, h: 0.15, fill: { color: COLORS.primary } });
  slide.addText("Length", { x: 3.35, y: legendY, w: 0.8, h: 0.3, fontSize: 9, fontFace: "Calibri", color: COLORS.textMuted });
  slide.addShape(pres.shapes.RECTANGLE, { x: 4.2, y: legendY + 0.08, w: 0.3, h: 0.15, fill: { color: COLORS.negative } });
  slide.addText("Reward", { x: 4.55, y: legendY, w: 0.8, h: 0.3, fontSize: 9, fontFace: "Calibri", color: COLORS.textMuted });
  slide.addShape(pres.shapes.RECTANGLE, { x: 5.4, y: legendY + 0.08, w: 0.3, h: 0.15, fill: { color: COLORS.textMuted } });
  slide.addText("Implicit", { x: 5.75, y: legendY, w: 0.8, h: 0.3, fontSize: 9, fontFace: "Calibri", color: COLORS.textMuted });

  // ============================================
  // SLIDE 5: Length-Adaptive GAE
  // ============================================
  slide = pres.addSlide();
  slide.background = { color: COLORS.lightBg };

  // Title
  slide.addText("Length-Adaptive GAE", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 34, fontFace: "Arial Black", color: COLORS.text, margin: 0
  });
  slide.addText("Dynamic λ Adjustment for Variable Response Lengths", {
    x: 0.5, y: 0.9, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Calibri", color: COLORS.textMuted
  });

  // Main concept box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.5, w: 9, h: 1.2,
    fill: { color: COLORS.white }, shadow: makeShadow()
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.5, w: 0.08, h: 1.2, fill: { color: COLORS.primary }
  });
  slide.addText("Core Insight", {
    x: 0.75, y: 1.6, w: 8.6, h: 0.35,
    fontSize: 14, fontFace: "Calibri", color: COLORS.primary, bold: true, margin: 0
  });
  slide.addText("The λ parameter in GAE controls the bias-variance tradeoff: low λ reduces variance but increases bias, while high λ reduces bias but increases variance. Different response lengths need different tradeoffs.", {
    x: 0.75, y: 1.95, w: 8.6, h: 0.65,
    fontSize: 13, fontFace: "Calibri", color: COLORS.text
  });

