    });

    // Text
    slide.addText(t.text, {
      x: 1.1, y: y + 0.1, w: 8.4, h: takeH - 0.1,
      fontSize: 13, fontFace: "Calibri", color: COLORS.white, valign: "middle"
    });
  });

  // Footer
  slide.addText("VAPO: Value-Model-Based RL for Advanced Reasoning  |  ByteDance Seed  |  arXiv:2504.05118", {
    x: 0.5, y: 5.25, w: 9, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: COLORS.textMuted
  });

  // Save presentation
  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Presentation saved to /app/output/final_deck.pptx");
}

